import base64
import hashlib
import hmac
import json

def _decode(segment):
    return base64.urlsafe_b64decode(segment + "=" * (-len(segment) % 4))

def _number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)

def validateJwt(token, secret, now, audience):
    if not isinstance(token, str):
        return "malformed"
    parts = token.split(".")
    if len(parts) != 3:
        return "malformed"
    try:
        header = json.loads(_decode(parts[0]))
        payload = json.loads(_decode(parts[1]))
    except Exception:
        return "malformed"
    if not isinstance(header, dict) or not isinstance(payload, dict):
        return "malformed"
    if header.get("alg") != "HS256":
        return "bad-alg"
    signed = (parts[0] + "." + parts[1]).encode("ascii", "replace")
    expected = hmac.new(secret.encode("utf-8"), signed, hashlib.sha256).digest()
    try:
        supplied = _decode(parts[2])
    except Exception:
        return "bad-signature"
    if not hmac.compare_digest(supplied, expected):
        return "bad-signature"
    exp = payload.get("exp")
    if not _number(exp) or now >= exp:
        return "expired"
    nbf = payload.get("nbf")
    if _number(nbf) and now < nbf:
        return "not-yet-valid"
    aud = payload.get("aud")
    if isinstance(aud, str):
        if aud != audience:
            return "bad-audience"
    elif isinstance(aud, list):
        if audience not in aud:
            return "bad-audience"
    else:
        return "bad-audience"
    return payload

