def buildQuery(filters, allowed):
    clauses, params = [], []
    for col in sorted(filters):
        if col not in allowed:
            return None
        val = filters[col]
        if val is None:
            clauses.append(col + " IS NULL")
        elif isinstance(val, list):
            if not val:
                clauses.append("1 = 0")
            else:
                clauses.append(col + " IN (" + ", ".join("?" for _ in val) + ")")
                params.extend(val)
        else:
            clauses.append(col + " = ?")
            params.append(val)
    sql = "SELECT * FROM users"
    if clauses:
        sql += " WHERE " + " AND ".join(clauses)
    return [sql, params]

